import{_ as l,o as a,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2018-08-09 Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-08-09 Ceph Performance Weekly","date":"2018-08-09T00:00:00.000Z","updated":"2018-08-09T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","存储集群","蓝店（Blue Store）"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-08-09_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-08-09_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),t={name:"posts/2018/2018-08-09_Ceph_Performance_Weekly.md"};function o(n,e,s,u,p,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Casey, Mark, Sage, Igor, Radek, Gregor, Jason, Braddock, Shawn Peng, Alfredo, Ari</li></ul><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><ul><li>日期：未提供</li><li>时间：未提供</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Request 复活</strong></p><ul><li>讨论了复活一个旧的Pull Request，该请求涉及重新启动一个关于维护顺序的复杂实现。</li></ul></li><li><p><strong>Radek的加密工作</strong></p><ul><li>Radek介绍了他在加密方面的工作，特别是关于使用低级AES实现的问题，讨论了与设置成本和实际加速之间的关系。</li></ul></li><li><p><strong>Igor的Tiny Appends Pull Request</strong></p><ul><li>Igor介绍了他的Tiny Appends Pull Request，该请求涉及在数据库中直接存储小对象，讨论了性能结果和潜在的改进。</li></ul></li><li><p><strong>EC Partial Stripe Reads</strong></p><ul><li>讨论了新的EC Partial Stripe Reads，需要进一步的审查。</li></ul></li><li><p><strong>RGW Up Tracker优化</strong></p><ul><li>讨论了RGW Up Tracker的优化，包括合并的请求和未合并的优化。</li></ul></li><li><p><strong>MVS Balancer和Blue Store Shard Completions</strong></p><ul><li>讨论了MVS Balancer的工作和Blue Store中的Shard Completions，特别是关于性能测试和线程配置的问题。</li></ul></li><li><p><strong>EDP配置选项和设备模板</strong></p><ul><li>讨论了EDP配置选项和设备模板，特别是关于如何简化用户设置和避免配置混乱的问题。</li></ul></li><li><p><strong>Blue Store的Tiny Writes优化</strong></p><ul><li>Igor详细介绍了Blue Store的Tiny Writes优化，包括性能测试结果和不同方法的比较。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步审查和测试EC Partial Stripe Reads。</li><li>RGW Up Tracker的优化将继续进行，包括更详细的性能数据。</li><li>需要对Blue Store的Tiny Writes进行更深入的性能测试，特别是在实际使用场景中。</li><li>对于EDP配置选项和设备模板，决定不引入新的HDD/SSD设置，而是保持现有选项，避免用户混淆。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>对EC Partial Stripe Reads进行详细审查和测试。</li><li>继续优化RGW Up Tracker，提供更多性能数据。</li><li>对Blue Store的Tiny Writes进行实际使用场景的性能测试，特别是关注RocksDB的compaction负载。</li><li>继续讨论和优化EDP配置选项和设备模板，确保用户设置的简化和清晰。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了RocksDB的compaction负载和如何更好地配置RocksDB的存储空间。</li><li>讨论了Blue Store的存储配置和如何动态调整数据库卷的大小。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在感谢所有参与者的贡献后结束。</li></ul>',15)])])}const _=l(t,[["render",o]]);export{c as __pageData,_ as default};
